{"parentUuid":"e3d307ff-3372-4782-b0d2-ae9cc13a7008","isSidechain":true,"userType":"external","cwd":"/Users/dm/orca/workspaces/HarnessHub/main-2","sessionId":"4599393d-122f-4857-bdd6-6aa56e152a10","version":"2.1.62","gitBranch":"devgraph/issue-prompt-only-line-budget-20260802","agentId":"a5c712a339fa69ce8","slug":"vectorized-fluttering-mochi","type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01T4k5J4LXwHNkM4X7JiKnNM","type":"tool_result","content":"     1→#!/usr/bin/env python3\n     2→# /// script\n     3→# name: validate-coverage-matrix\n     4→# version: 0.1.0\n     5→# purpose: システム構成カテゴリ×canonical platform id の収集マトリクスの全セルが『未収集/対象外/確定』のいずれかで埋まり、対象外に理由・確定に qa_ref が付与され、必須プラットフォーム行が全存在し、カテゴリ集約状態が真理値表と一致し、参照先 ID (qa_log/approval_log/categories/goals) が一意であることを検証する決定論ゲート (goal-spec C7 の直接実装)。\n     6→# inputs:\n     7→#   - argv: --matrix FILE [--require-complete]\n     8→# outputs:\n     9→#   - stdout: OK summary\n    10→#   - stderr: violation 一覧\n    11→#   - exit: 0=OK / 1=violation / 2=usage error\n    12→# contexts: [E, C]\n    13→# network: false\n    14→# write-scope: none\n    15→# dependencies: [coverage_foundation.py]\n    16→# requires-python: \">=3.9\"\n    17→# ///\n    18→\"\"\"カテゴリ×プラットフォーム収集マトリクス (spec-state.json) の網羅性を機械検証する。\n    19→\n    20→matrix ファイル (spec-state.json) の期待形状:\n    21→{\n    22→  \"categories\": [{\"id\": \"database\", \"label\": \"データベース\"}, ...],\n    23→  \"platforms\": [\"web\",\"mobile\",\"tablet\",\"desktop-windows\",\"desktop-linux\",\"desktop-macos\"],\n    24→  \"matrix\": {\n    25→    \"<category_id>\": {\n    26→      \"<platform_id>\": {\"state\": \"確定\", \"qa_ref\": \"qa-001\"},        # 確定は qa_ref 必須\n    27→      \"<platform_id>\": {\"state\": \"対象外\", \"reason\": \"...\"},          # 対象外は reason 必須\n    28→      \"<platform_id>\": {\"state\": \"未収集\"}                            # loop 中のみ許容\n    29→    }, ...\n    30→  },\n    31→  \"qa_log\": [{\"id\": \"qa-001\", ...}],          # 確定 qa_ref の参照先 (存在検証 + id 一意性検証)\n    32→  \"approval_log\": [{\"id\": \"appr-001\", ...}],  # 一括承認 (対象外/確定を承認ログ参照で代替可・id 一意)\n    33→  \"category_aggregate\": {\"<category_id>\": \"確定\"|\"収集中\"|\"未着手\"|\"対象外\"}  # 任意 (あれば真理値表照合)\n    34→}\n    35→\n    36→集約状態の真理値表 (goal-spec C1 の 4 値):\n    37→  全セル未収集              -> 未着手\n    38→  未収集混在 (一部のみ未収集) -> 収集中\n    39→  全セル対象外              -> 対象外\n    40→  それ以外で未収集 0        -> 確定\n    41→\n    42→ID 一意性 (fail-closed・既定で有効): qa_log / approval_log / categories / goals の id は参照先を\n    43→識別する前提なので、集合へ正規化する前に出現順で走査して重複を検出する。集合内包で組み立てると\n    44→重複 id が黙って 1 件へ畳み込まれ、二重採番が「参照先は実在する」という緑のまま通り抜ける\n    45→(issues/sys-qa-log-id-uniqueness-gate-20260726.md)。\n    46→\n    47→要件 C9 (上位概念 anchor・opt-in): --require-foundation を付けると validate_foundation() が\n    48→requirements_foundation の U1-U5 非空・各『確定』セルの serves_goals トレース (実在 goal へ ≥1)・\n    49→どのゴールにも資さない確定セル (drift 候補) を追加検証する。既定 (--matrix / --require-complete) は\n    50→従来どおりで validate() を一切変えないため後方互換 (foundation 検証は完全にオプトイン)。\n    51→検証本体は同ディレクトリの coverage_foundation.py (import-only support module) にある。\n    52→\"\"\"\n    53→from __future__ import annotations\n    54→\n    55→import argparse\n    56→import json\n    57→import sys\n    58→from pathlib import Path\n    59→\n    60→HERE = Path(__file__).resolve().parent\n    61→if str(HERE) not in sys.path:\n    62→    sys.path.insert(0, str(HERE))\n    63→\n    64→from coverage_foundation import validate_foundation\n    65→\n    66→CELL_STATES = {\"未収集\", \"対象外\", \"確定\"}\n    67→CANONICAL_PLATFORMS = (\n    68→    \"web\",\n    69→    \"mobile\",\n    70→    \"tablet\",\n    71→    \"desktop-windows\",\n    72→    \"desktop-linux\",\n    73→    \"desktop-macos\",\n    74→)\n    75→# goal-spec C1 の例示カテゴリ (canonical id)。マトリクスはこれを最低含むか除外根拠を持つ。\n    76→GOAL_SPEC_CATEGORIES = (\n    77→    \"database\",\n    78→    \"auth\",\n    79→    \"ui-ux\",\n    80→    \"security\",\n    81→    \"infrastructure\",\n    82→    \"backend\",\n    83→    \"frontend\",\n    84→    \"maintenance-ops\",\n    85→)\n    86→\n    87→\n    88→def _collect_unique_ids(entries, label: str) -> tuple[set[str], list[str]]:\n    89→    \"\"\"id 付きエントリ列から一意な ID 集合を作り、id の欠落と重複を finding として返す。\n    90→\n    91→    集合内包 ({e.get(\"id\") for e in ...}) で組み立てると重複 id が黙って 1 件へ畳み込まれ、\n    92→    「参照先が一意か」という前提が検査される前に消える (= 二重採番の無検出)。\n    93→    正規化より先に検査するため、出現順に走査して重複を明示的に検出する。\n    94→\n    95→    Returns:\n    96→        (一意な id の集合, findings)。findings が非空なら呼び出し側が違反として扱う。\n    97→    \"\"\"\n    98→    findings: list[str] = []\n    99→    seen: set[str] = set()\n   100→    counts: dict[str, int] = {}\n   101→    if not isinstance(entries, list):\n   102→        if entries is not None:\n   103→            findings.append(f\"{label}: 配列でない\")\n   104→        return seen, findings\n   105→\n   106→    for i, entry in enumerate(entries):\n   107→        if not isinstance(entry, dict):\n   108→            findings.append(f\"{label}[{i}]: エントリがオブジェクトでない\")\n   109→            continue\n   110→        eid = entry.get(\"id\")\n   111→        if not eid:\n   112→            findings.append(f\"{label}[{i}]: id 欠落\")\n   113→            continue\n   114→        if not isinstance(eid, str):\n   115→            findings.append(f\"{label}[{i}]: id が文字列でない ({eid!r})\")\n   116→            continue\n   117→        if eid in seen:\n   118→            counts[eid] = counts.get(eid, 1) + 1\n   119→        else:\n   120→            seen.add(eid)\n   121→\n   122→    for eid in sorted(counts):\n   123→        findings.append(\n   124→            f\"{label}: id={eid!r} が {counts[eid]} 件重複\"\n   125→            \" (ID が一意でなければ参照先を識別できない)\"\n   126→        )\n   127→    return seen, findings\n   128→\n   129→\n   130→def _derive_aggregate(cells: list[str]) -> str:\n   131→    \"\"\"セル状態集合から真理値表でカテゴリ集約状態を導出する。\"\"\"\n   132→    if all(c == \"未収集\" for c in cells):\n   133→        return \"未着手\"\n   134→    if all(c == \"対象外\" for c in cells):\n   135→        return \"対象外\"\n   136→    if any(c == \"未収集\" for c in cells):\n   137→        return \"収集中\"\n   138→    return \"確定\"\n   139→\n   140→\n   141→def validate(data: dict, require_complete: bool = False) -> list[str]:\n   142→    findings: list[str] = []\n   143→\n   144→    categories = data.get(\"categories\")\n   145→    matrix = data.get(\"matrix\")\n   146→    if not isinstance(categories, list) or not categories:\n   147→        findings.append(\"categories: 非空配列でない\")\n   148→        return findings\n   149→    if not isinstance(matrix, dict) or not matrix:\n   150→        findings.append(\"matrix: 非空オブジェクトでない\")\n   151→        return findings\n   152→\n   153→    cat_ids = []\n   154→    for c in categories:\n   155→        if not isinstance(c, dict) or not c.get(\"id\"):\n   156→            findings.append(f\"categories: id 欠落エントリ ({c!r})\")\n   157→            continue\n   158→        # 重複 category id は同一 matrix 行を二重評価し、片方の定義を静かに握り潰す\n   159→        if c[\"id\"] in cat_ids:\n   160→            findings.append(f\"categories: id={c['id']!r} が重複 (matrix 行が二重に評価される)\")\n   161→            continue\n   162→        cat_ids.append(c[\"id\"])\n   163→\n   164→    # カテゴリ軸床: goal-spec 例示カテゴリを最低含むか除外根拠 (excluded_categories) を持つ\n   165→    excluded = set(data.get(\"excluded_categories\", {}) or {})\n   166→    missing_cat = [\n   167→        g for g in GOAL_SPEC_CATEGORIES if g not in cat_ids and g not in excluded\n   168→    ]\n   169→    if missing_cat:\n   170→        findings.append(\n   171→            f\"カテゴリ軸床: goal-spec 例示カテゴリ {missing_cat} が未定義かつ除外根拠 (excluded_categories) 無し\"\n   172→        )\n   173→\n   174→    # 参照先 ID の一意性検査 (集合化で重複を潰す前に検査する)\n   175→    qa_ids, qa_findings = _collect_unique_ids(data.get(\"qa_log\"), \"qa_log\")\n   176→    approval_ids, approval_findings = _collect_unique_ids(data.get(\"approval_log\"), \"approval_log\")\n   177→    findings.extend(qa_findings)\n   178→    findings.extend(approval_findings)\n   179→    # 両ログは ref_ids へ統合されるため、ログを跨いだ id 衝突も参照先を一意に定められなくする\n   180→    collision = sorted(qa_ids & approval_ids)\n   181→    if collision:\n   182→        findings.append(\n   183→            f\"qa_log/approval_log: id {collision} が両ログに重複 (qa_ref の参照先が一意に定まらない)\"\n   184→        )\n   185→    ref_ids = qa_ids | approval_ids\n   186→\n   187→    unresolved = 0\n   188→    for cat_id in cat_ids:\n   189→        row = matrix.get(cat_id)\n   190→        if not isinstance(row, dict):\n   191→            findings.append(f\"matrix[{cat_id}]: 行が存在しない/オブジェクトでない\")\n   192→            continue\n   193→\n   194→        # 必須プラットフォーム行の全存在\n   195→        missing_pf = [p for p in CANONICAL_PLATFORMS if p not in row]\n   196→        if missing_pf:\n   197→            findings.append(f\"matrix[{cat_id}]: 必須 platform {missing_pf} が欠落\")\n   198→\n   199→        cells: list[str] = []\n   200→        for pf in CANONICAL_PLATFORMS:\n   201→            cell = row.get(pf)\n   202→            if cell is None:\n   203→                continue\n   204→            if not isinstance(cell, dict):\n   205→                findings.append(f\"matrix[{cat_id}][{pf}]: セルがオブジェクトでない\")\n   206→                continue\n   207→            state = cell.get(\"state\")\n   208→            if state not in CELL_STATES:\n   209→                findings.append(\n   210→                    f\"matrix[{cat_id}][{pf}]: state={state!r} が {sorted(CELL_STATES)} 外\"\n   211→                )\n   212→                continue\n   213→            cells.append(state)\n   214→            if state == \"未収集\":\n   215→                unresolved += 1\n   216→            elif state == \"対象外\":\n   217→                if not (cell.get(\"reason\") or cell.get(\"approval_ref\") in approval_ids):\n   218→                    findings.append(\n   219→                        f\"matrix[{cat_id}][{pf}]: 対象外だが reason も approval_ref も無い\"\n   220→                    )\n   221→            elif state == \"確定\":\n   222→                qa_ref = cell.get(\"qa_ref\")\n   223→                if not qa_ref:\n   224→                    findings.append(f\"matrix[{cat_id}][{pf}]: 確定だが qa_ref が空\")\n   225→                elif qa_ref not in ref_ids:\n   226→                    findings.append(\n   227→                        f\"matrix[{cat_id}][{pf}]: 確定 qa_ref={qa_ref!r} が qa_log/approval_log に不在\"\n   228→                    )\n   229→\n   230→        # 集約状態の真理値表照合 (宣言があれば)\n   231→        declared = (data.get(\"category_aggregate\") or {}).get(cat_id)\n   232→        if declared is not None and cells:\n   233→            derived = _derive_aggregate(cells)\n   234→            if declared != derived:\n   235→                findings.append(\n   236→                    f\"matrix[{cat_id}]: category_aggregate={declared!r} が真理値表導出 {derived!r} と不一致\"\n   237→                )\n   238→\n   239→    if require_complete and unresolved:\n   240→        findings.append(f\"未収集セルが {unresolved} 件残存 (最終時は未収集 0 が必須)\")\n   241→\n   242→    return findings\n   243→\n   244→\n   245→def main(argv: list[str]) -> int:\n   246→    ap = argparse.ArgumentParser(description=\"収集マトリクス網羅性の決定論検証 (goal-spec C7)\")\n   247→    ap.add_argument(\"--matrix\", required=True, help=\"spec-state.json のパス\")\n   248→    ap.add_argument(\n   249→        \"--require-complete\",\n   250→        action=\"store_true\",\n   251→        help=\"最終時: 未収集セル 0 を必須にする (OUT1/C7 受入)\",\n   252→    )\n   253→    ap.add_argument(\n   254→        \"--require-foundation\",\n   255→        action=\"store_true\",\n   256→        help=\"上位概念 (requirements_foundation U1-U9 値ありまたは明示N/A)・decisions・goalトレースを検証 (C9・opt-in)\",\n   257→    )\n   258→    args = ap.parse_args(argv)\n   259→\n   260→    path = Path(args.matrix)\n   261→    if not path.is_file():\n   262→        print(f\"matrix ファイルが存在しない: {args.matrix}\", file=sys.stderr)\n   263→        return 2\n   264→    try:\n   265→        data = json.loads(path.read_text(encoding=\"utf-8\"))\n   266→    except (json.JSONDecodeError, UnicodeDecodeError) as exc:\n   267→        print(f\"matrix ファイルの JSON parse 失敗: {exc}\", file=sys.stderr)\n   268→        return 2\n   269→\n   270→    findings = validate(data, require_complete=args.require_complete)\n   271→    if args.require_foundation:\n   272→        findings += validate_foundation(data)\n   273→    if findings:\n   274→        for f in findings:\n   275→            print(f\"VIOLATION: {f}\", file=sys.stderr)\n   276→        print(f\"FAIL: {len(findings)} 件の網羅性違反\", file=sys.stderr)\n   277→        return 1\n   278→    mode = \"final(未収集0)\" if args.require_complete else \"loop\"\n   279→    if args.require_foundation:\n   280→        mode += \"+foundation(上位概念トレース)\"\n   281→    print(f\"OK: 収集マトリクス網羅性 ({mode}) を満たす\")\n   282→    return 0\n   283→\n   284→\n   285→if __name__ == \"__main__\":\n   286→    sys.exit(main(sys.argv[1:]))\n   287→"}]},"uuid":"cdd44e06-d518-48cf-88fa-698dd6eff871","timestamp":"2026-08-02T14:59:45.636Z","sourceToolAssistantUUID":"e3d307ff-3372-4782-b0d2-ae9cc13a7008"}
